INSERT INTO `ippd_penilaian` (
    `kodewilayah`, `tahun`, `item_code`, `bobot_capaian`, `opsi_aksi`, `catatan`, `detail_json`, `status_verifikasi`, `created_at`, `updated_at`
) VALUES (
    '35.10', 2026, '2.a.1.a', 5.6, 'Penyusunan kebutuhan daerah > 75% s/d <= 99% hasil evaluasi', 'Hasil penarikan evaluasi keselarasan permasalahan daerah', '{"rows":[{"no":1,"permasalahan":"Belum signifikan penurunan kemiskinan di Kabupaten Banyuwangi","evaluasi":"Angka kemiskinan ekstrem memiliki kecenderungan menurun akan tetapi belum optimal","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":2,"permasalahan":"Kurangnya tingkat serapan angkatan kerja","evaluasi":"- Penyerapan tenaga kerja masih didominasi oleh penduduk yang bekerja di kegiatan informal, proposi Penyerapan tenaga kerja oleh penduduk yang bekerja pada kegiatan informal meskipun sudah menurun yaitu dari 64.51 persen di tahun 2020 menjadi 63.55 persen di tahun 2024. - Penurunan Tingkat Partisipasi Angkatan Kerja (TPAK) ditengah meningkatnya jumlah penduduk usia kerja. penurunan TPAK di Kabupaten Banyuwangi dari 79.04 persen di tahun 2023 menjadi 75.36 persen di tahun 2024, meskipun kondisi ini lebih baik dibandingkan tahun 2020 dimana TPAK hanya sebesar 71.80 persen. Kondisi ini menggambarkan adanya stagnasi atau bahkan penurunan aktivitas ekonomi di masyarakat, yang apabila tidak ditangani menyebabkan meningkatnya beban sosial, kesenjangan ekonomi, dan penurunan produktivitas ekonomi.","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":3,"permasalahan":"Masih adanya angka putus sekolah","evaluasi":"Kabupaten Banyuwangi berkomitmen membangun pendidikan yang inklusif dan berkualitas melalui berbagai program dan inovasi yang memperluas aksesibilitas bagi seluruh masyarakat, terutama kelompok rentan dan kurang mampu. Namun, tantangan ke depan tetap harus diantisipasi, seperti perubahan dinamika sosial, perkembangan teknologi, dan tuntutan dunia kerja yang semakin kompetitif.","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":4,"permasalahan":"Rerata kemampuan Numerasi SMP berdasarkan asesmen nasional menurun 2023","evaluasi":"Capaian Kemampuan dan Kemampuan Numerasi masih belum maksimal.","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":5,"permasalahan":"capaian indikator SPM kesehatan pada tahun 2023 menurun, indikatornya Pelayanan Kesehatan Ibu Hamil dan pelayanan lanjut usia","evaluasi":"Belum optimalnya kunjungan ibu hamil di trimester pertama karena:a) budaya masyarakat yang tabu memeriksakan kehamilan saat masih dibawah 4 bulanb) Kehamilan yang disembunyikan (kehamilan anak, kehamilan tidak diinginkan)c) Kesadaran masyarakat yang kurang.","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":6,"permasalahan":"potensi stunting yang cukup tinggi","evaluasi":"Balita stunting mengalami penurunan akan tetapi belum cukup signifikan apabila dibandingkan dengan peningkatan yang terjadi pada periode sebelumnya","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":7,"permasalahan":"jumlah kunjungan wisatawan dan lama tinggal belum dapat mencapai kembali angka seperti ditahun 2019 sebelum covid","evaluasi":"Keterbatasan dalam kualitas SDM disektor pariwisata, seperti kurangnya pelatihan dan sertifikasi bagi tenaga kerja, dapat memengaruhi pelayanan kepada wisatawan dan daya saing destinasi","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":8,"permasalahan":"Daya saing UMKM belum optimal","evaluasi":"Minimnya akses modal bagi usaha mikro","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":9,"permasalahan":"Perlambatan PDRB sektor Pertanian","evaluasi":"sektor unggulan masih mendukung perekonomian daerah, kontraksi pada sektor Pertanian, Kehutanan, dan Perikanan menjadi tantangan tersendiri, mengingat kontribusinya yang masih dominan. Hal ini perlu menjadi perhatian dalam perencanaan strategis ke depan, terutama dalam penguatan ketahanan sektor pertanian dan diversifikasi sumber pertumbuhan ekonomi.","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":10,"permasalahan":"perubahan budaya terutama pada generasi Z","evaluasi":"Belum optimalnya pelestarian dan pengembangan budaya lokal di Kabupaten Banyuwangi","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":11,"permasalahan":"Perubahan iklim.","evaluasi":"Meskipun Kapasitas Kabupaten Banyuwangi dalam penanggulangan bencana terus meningkat, masih terdapat beberapa kendala dalam upaya perkuatan kesiapsiagaan dan penanganan darurat bencana di Kabupaten Banyuwangi terutama pada beberapa tantangan yang ada yakni:1. Kesiapan dalam penyusunan Rencana Kontinjensi untuk setiap ancaman bencana.2. Sistem peringatan dini yang belum optimal untuk setiap jenis ancaman.3. Ketersediaan jalur dan tempat evakuasi sementara yang memadai.4. Mekanisme penentuan status tanggap darurat dan penerapan sistem komando operasi darurat.5. Peningkatan efektivitas dalam pengerahan Tim Kaji Cepat dan Tim Penyelamatan Korban.6. Tantangan dalam pengorganisasian bantuan bagi masyarakat terdampak di wilayah terpencil.7. Mekanisme penghentian status tanggap darurat bencana.","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":12,"permasalahan":"Persentase Sampah yang Dikelola kecenderungan menurun","evaluasi":"Pengelolaan Sampah, wisata alam secara utama memiliki masalah sampah, terutama di area pantai karena sifatnya adalah sampah kiriman sehingga jika tidak dikelola dengan baik terjadi penumpukan sampah tidak hanya merusak estetika lingkungan tetapi juga dapat menurunkan citra pariwisata.","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":13,"permasalahan":"Kualitas lingkungan Hidup meningkat, tetapi tidak lebih baik di bandingkan angka 2019","evaluasi":"Meskipun Banyuwangi dikenal dengan kekayaan alamnya yang luar biasa, mulai dari pegunungan, hutan, hingga pesisir yang luas, yang membuatnya sangat potensial untuk sektor industri dan pariwisata, perkembangan sektor-sektor ini juga membawa tantangan besar bagi kelestarian lingkungan. Kegiatan industri dan pariwisata yang meningkat berisiko memberi tekanan pada ekosistem.","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":14,"permasalahan":"Aplikasi pemerintahan belum di integrasikan karena belum terwujud dengan super apps","evaluasi":"","nilai_keselarasan":0,"keterangan":"Tidak Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""},{"no":15,"permasalahan":"Jalan kondisi baik menurun di tahun 2023","evaluasi":"Infrastruktur, pembangunan infrustuktur membutuhkan sumberdaya yang tidak sedikit terutama dalam mendukung destinasi wisata di Banyuwangi mulai dari akses jalan, fasilitas umum pariwisata sehingga perlu skala prioritas dalam pembangunan insfratruktur pendukung pariwisata","nilai_keselarasan":100,"keterangan":"Terdapat Keterkaitan permasalahan daerah (kebutuhan daerah) dengan hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":""}],"total_rows":15,"matched_count":14,"pct_matched":93.33,"keselarasan_terbobot":5.6,"kriteria":"D","score":5.6,"opsi_aksi":"Penyusunan kebutuhan daerah > 75% s/d <= 99% hasil evaluasi","dokumen":"LPPD Tahun 2024","halaman":"","tabel":"","catatan":"Hasil penarikan evaluasi keselarasan permasalahan daerah"}', 'Draft', '2026-11-17 08:04:04', '2026-11-17 08:04:04'
)
