    '35.10', 2026, '2.a.1.b', 6, 'Kesesuaian 100%', 'Hasil penarikan keterkaitan Prioritas Pembangunan Daerah dengan Permasalahan Pembangunan', '{"groups":[{"prioritas":"PD 1. Peningkatan Produksi Pangan","keterangan":"Terdapat Dukungan Program Pembangunan Daerah untuk mendukung Program Prioritas Pembangunan Nasional terkait","perms":[{"permasalahan":"Minat bertani berkurang kesejahteraan petani kususnya pada buruh tani","nilai_keselarasan":100},{"permasalahan":"Lahan produktif mulai berkurang","nilai_keselarasan":100},{"permasalahan":"Kesejahteraan petani yang belum optimal","nilai_keselarasan":100},{"permasalahan":"Adanya ancaman penyakit menular dan tidak menular terhadap hewan ternak","nilai_keselarasan":100},{"permasalahan":"Adanya ketergantungan terhada pupuk sehingga menyebabkan penurunan kesuburan lahan pertanian","nilai_keselarasan":100},{"permasalahan":"Produksi perikanan mengalami penurunan","nilai_keselarasan":100},{"permasalahan":"Konsumsi ikan masih rendah hilirasasi produk perikanan","nilai_keselarasan":100}]},{"prioritas":"PD 2. Peningkatan Nilai Tambah Produk UMKM","keterangan":"Terdapat Dukungan Program Pembangunan Daerah untuk mendukung Program Prioritas Pembangunan Nasional terkait","perms":[{"permasalahan":"Belum optimalnya tata kelola sumber daya koperasi","nilai_keselarasan":100},{"permasalahan":"Minimnya diversifikasi usaha koperasi","nilai_keselarasan":100},{"permasalahan":"Akses permodalan dan akses pasar","nilai_keselarasan":100},{"permasalahan":"serta belum siapnya usaha masyarakat yang beradaptasi dengan teknogi dan pemasaran","nilai_keselarasan":100}]},{"prioritas":"3. Perluasan Pasar Sektor Pertanian Dan Pariwisata","keterangan":"Terdapat Dukungan Program Pembangunan Daerah untuk mendukung Program Prioritas Pembangunan Nasional terkait","perms":[{"permasalahan":"Hilirisasi dan jaringan keperantaraan pasar sektor pertanian","nilai_keselarasan":100},{"permasalahan":"Minimnya promosi serta pengembangan atraksi dan sarana pendukung pariwisata","nilai_keselarasan":100},{"permasalahan":"Belum efektif dan efisiennya jaringan distribusi perdagangan melalui penataan sistem dan sarana distribusi","nilai_keselarasan":100}]},{"prioritas":"4. Peningkatan Serapan Tenaga Kerja Dalam Sektor UMKM Dan Pariwisata","keterangan":"Terdapat Dukungan Program Pembangunan Daerah untuk mendukung Program Prioritas Pembangunan Nasional terkait","perms":[{"permasalahan":"Tidak tersedianya lapangan pekerjaan yang sesuai dengan keterampilan dan pengalaman yang dimiliki oleh para pencari kerja.","nilai_keselarasan":100},{"permasalahan":"Serapan tenaga kerja di banyuwangi masih belum optimal","nilai_keselarasan":100},{"permasalahan":"Tingkat pengangguran yang masih tergolong tinggi","nilai_keselarasan":100},{"permasalahan":"Lemahnya daya tarik investasi","nilai_keselarasan":100}]},{"prioritas":"5. Peningkatan Akses Infrastruktur Pariwisata dan Pertanian serta Peningkatan Ketahanan Lingkungan Hidup","keterangan":"Terdapat Dukungan Program Pembangunan Daerah untuk mendukung Program Prioritas Pembangunan Nasional terkait","perms":[{"permasalahan":"IPLT yang ada sekarang tidak dapat menampung kebutuhan","nilai_keselarasan":100},{"permasalahan":"Penumpukan sampah yang tidak di daur ulang","nilai_keselarasan":100},{"permasalahan":"Belum optimalnya pengelolaan sampah berkelanjutan di wilayah selain wilayah kota","nilai_keselarasan":100},{"permasalahan":"Masih rendahnya kesadaran masyarakat terhadap pengelolaan sampah","nilai_keselarasan":100},{"permasalahan":"Masih tingginya Pencemaran air dan udara","nilai_keselarasan":100},{"permasalahan":"Kerusakan alam dan perubahan iklim mengancam keberlanjutan lingkungan dan kesejahteraan manusia","nilai_keselarasan":100},{"permasalahan":"Infrastuktur jalan dan jembatan serta konektivitas daerah belum optimal","nilai_keselarasan":100},{"permasalahan":"Kondisi drainase yang belum bisa menampung air hujan","nilai_keselarasan":100},{"permasalahan":"Terdapat Konflik kepentingan antar petani terkait pembagian air","nilai_keselarasan":100},{"permasalahan":"Pemanfaatan lahan masih belum sesuai peruntukan, belum optimalnya pengembangan jaringan irigasi","nilai_keselarasan":100},{"permasalahan":"Masih terdapat sumber mata air inactive","nilai_keselarasan":100},{"permasalahan":"Belum adanya dokumen RDTRK menuju digitalisasi dan terintegrasi dengan aplikasi perizinan digital","nilai_keselarasan":100},{"permasalahan":"Penerapan industri yang ramah lingkungan (green industry) belum optimal","nilai_keselarasan":100}]},{"prioritas":"6. Perlindungan Sosial Adaptif Dan Pemberdayaan Masyarakat Miskin Dan Rentan","keterangan":"Terdapat Dukungan Program Pembangunan Daerah untuk mendukung Program Prioritas Pembangunan Nasional terkait","perms":[{"permasalahan":"Terjadi peningkatan kekerasan perempuan dan anak","nilai_keselarasan":100},{"permasalahan":"Terjadi kerentananan kualitas keluarga yang berdampak pada peningkatan perilaku menyimpang di kalangan individu","nilai_keselarasan":100},{"permasalahan":"Ketidaktepatan sasaran bantuan sosial karena data belum tepat","nilai_keselarasan":100},{"permasalahan":"Kurang sinerginya pihak terkait dalam pelayanan PMKS","nilai_keselarasan":100},{"permasalahan":"Penanganan permukiman kumuh dan RTLH belum berjalan optimal","nilai_keselarasan":100}]},{"prioritas":"7. Penguatan Pendidikan Yang Berdaya Saing","keterangan":"Terdapat Dukungan Program Pembangunan Daerah untuk mendukung Program Prioritas Pembangunan Nasional terkait","perms":[{"permasalahan":"Masih belum meratanya kualitas Pendidikan","nilai_keselarasan":100},{"permasalahan":"Belum sepenuhnya kompetensi guru dalam penguasaan IT","nilai_keselarasan":100},{"permasalahan":"Sarpras sekolah belum memenuhi akses lengkap yang berkualitas","nilai_keselarasan":100},{"permasalahan":"Tantangan dalam mengimbangi Pendidikan dengan nilai karakter","nilai_keselarasan":100}]},{"prioritas":"8. Peningkatan Akses Kesehatan Dan Pola Hidup Sehat","keterangan":"Terdapat Dukungan Program Pembangunan Daerah untuk mendukung Program Prioritas Pembangunan Nasional terkait","perms":[{"permasalahan":"Infrastruktur kesehatan penyakit menular dan tidak menular yang berkualitas","nilai_keselarasan":100},{"permasalahan":"Belum meratanya jaminan Kesehatan","nilai_keselarasan":100},{"permasalahan":"Kenaikan angka kematian ibu","nilai_keselarasan":100},{"permasalahan":"Masih adanya kasus Stunting","nilai_keselarasan":100},{"permasalahan":"Belum Meratanya Sistem Kesehatan yang berkualitas","nilai_keselarasan":100}]},{"prioritas":"9. Reformasi Birokrasi","keterangan":"Terdapat Dukungan Program Pembangunan Daerah untuk mendukung Program Prioritas Pembangunan Nasional terkait","perms":[{"permasalahan":"Masih kurangnya kesadaran masyarakat terkait pentingnya data kependudukan","nilai_keselarasan":100},{"permasalahan":"Kurang maksimalnya integrasi digitalisasi layanan","nilai_keselarasan":100},{"permasalahan":"Penguatan sistem keuangan terintegrasi","nilai_keselarasan":100},{"permasalahan":"Intensifikasi dan ekstensifikasi PAD","nilai_keselarasan":100},{"permasalahan":"Kuantitas dan kualitas SDM peneliti belum memadai","nilai_keselarasan":100}]}],"total_rows":50,"matched_count":50,"pct_matched":100,"keselarasan_terbobot":6,"kriteria":"E","score":6,"opsi_aksi":"Kesesuaian 100%","dokumen":"RKPD Kabupaten Banyuwangi 2026","halaman":"","tabel":"","catatan":"Hasil penarikan keterkaitan Prioritas Pembangunan Daerah dengan Permasalahan Pembangunan"}', 'Draft', '2026-11-17 08:04:04', '2026-11-17 08:04:04'
