fratruktur Pariwisata dan Pertanian serta Peningkatan ketahanan Lingkungan hidup","nilai_keselarasan":100,"keterangan":"Terdapat Prioritas Pembangunan Daerah yang didasarkan kepada Isu Strategis"},{"prioritas":"Peningkatan Nilai Tambah Produk UMKM","nilai_keselarasan":100,"keterangan":"Terdapat Prioritas Pembangunan Daerah yang didasarkan kepada Isu Strategis"},{"prioritas":"Perluasan Pasar Sektor Pertanian Dan Pariwisata","nilai_keselarasan":100,"keterangan":"Terdapat Prioritas Pembangunan Daerah yang didasarkan kepada Isu Strategis"},{"prioritas":"Peningkatan Serapan Tenaga Kerja Dalam Sektor UMKM Dan Pariwisata","nilai_keselarasan":100,"keterangan":"Terdapat Prioritas Pembangunan Daerah yang didasarkan kepada Isu Strategis"}]}],"total_rows":11,"matched_count":11,"pct_matched":100,"keselarasan_terbobot":6,"kriteria":"E","score":6,"opsi_aksi":"Penyusunan 100% berdasarkan isu strategis","dokumen":"RKPD Kabupaten Banyuwangi 2026","halaman":"","tabel":"","catatan":"Hasil penarikan penyusunan prioritas pembangunan berdasarkan isu strategis"}', 'Draft', '2026-11-17 08:04:04', '2026-11-17 08:04:04'
